use vstd::prelude::*;

verus! {
    // We verify that:
    //   • N is in (0,1000)
    //   • a.len() == N
    //   • sum.len() == 1
    // and that after the call:
    //   • `a` is unchanged
    //   • sum.len() == 1
    //   • sum[0] == 4 * N
    fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32)
        requires
            0 < N,
            N < 1000,
            a.len() == N as usize,
            sum.len() == 1,
        ensures
            // `a` did not get mutated
            a@ == old(a@),
            // `sum` still has length 1
            sum@.len() == 1,
            // and its sole entry is now 4*N
            sum@[0] == 4 * N,
    {
        // Show that `4 * N` cannot overflow an i32
        // under the assumption N < 1000 ⇒ 4*N ≤ 4*999 = 3996 ≪ i32::MAX.
        assert(4 * N <= i32::MAX) by {
            // from N < 1000 we get 4*N ≤ 4*999 = 3996
            assert(N < 1000);
            assert(4 * N <= 3996);
            // 3996 is obviously ≤ i32::MAX
            assert(3996 <= i32::MAX);
        }

        // Now the actual implementation stays the same:
        sum[0] = 4 * N;
    }
}

